            <tr key={a.id}>
              <td className="mono">{a.container_no}</td>
              <td>{fmt(a.planned_time)}</td>
              <td>{a.truck_no}</td>
              <td><span className={`tag a-${a.status}`}>{STATUS[a.status]}</span></td>
              <td>{fmt(a.created_at)}</td>
              <td>
                {a.status === 'PENDING' &&
                  <button className="btn-sm" onClick={() => cancel(a)}>取消</button>}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
